import{_ as e,o as r,c as o,a6 as a}from"./chunks/framework.BrkgobfX.js";const m=JSON.parse('{"title":"MoE 的三个旋钮 · 专家数、激活数、共享专家","description":"同样是 MoE，DeepSeek 的“多而小 + 共享专家”、Llama 4 的“少而大”、Qwen3 的“砍掉共享专家”（以及 Qwen3.8 重新加回）为什么差这么多？拆开三个可调旋钮——专家总数与粒度、每 token 激活几个、要不要一个万金油共享专家——看各家的取舍逻辑。","frontmatter":{"title":"MoE 的三个旋钮 · 专家数、激活数、共享专家","description":"同样是 MoE，DeepSeek 的“多而小 + 共享专家”、Llama 4 的“少而大”、Qwen3 的“砍掉共享专家”（以及 Qwen3.8 重新加回）为什么差这么多？拆开三个可调旋钮——专家总数与粒度、每 token 激活几个、要不要一个万金油共享专家——看各家的取舍逻辑。","source":"https://daiw.org/manual/llm-anatomy/moe-knobs"},"headers":[],"relativePath":"manual/llm/llm-anatomy/moe-knobs.md","filePath":"manual/llm/llm-anatomy/moe-knobs.md"}'),n={name:"manual/llm/llm-anatomy/moe-knobs.md"};function d(s,t,l,i,g,h){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="moe-的三个旋钮-·-专家数、激活数、共享专家" tabindex="-1">MoE 的三个旋钮 · 专家数、激活数、共享专家 <a class="header-anchor" href="#moe-的三个旋钮-·-专家数、激活数、共享专家" aria-label="Permalink to &quot;MoE 的三个旋钮 · 专家数、激活数、共享专家&quot;">​</a></h1><blockquote><p>同样是 MoE，DeepSeek 的“多而小 + 共享专家”、Llama 4 的“少而大”、Qwen3 的“砍掉共享专家”（以及 Qwen3.8 重新加回）为什么差这么多？拆开三个可调旋钮——专家总数与粒度、每 token 激活几个、要不要一个万金油共享专家——看各家的取舍逻辑。</p></blockquote><p>“把前馈换成一堆专家”只是一句口号。真正把各家 MoE 区分开的，是三个可调的旋钮。把它们拧到不同位置，就得到 DeepSeek、Llama 4、Qwen、Kimi 那几种截然不同的风格。这一章，一个旋钮一个旋钮地拧。</p><h2 id="旋钮一-专家-多而小-还是-少而大" tabindex="-1">旋钮一：专家“多而小”还是“少而大” <a class="header-anchor" href="#旋钮一-专家-多而小-还是-少而大" aria-label="Permalink to &quot;旋钮一：专家“多而小”还是“少而大”&quot;">​</a></h2><p>同样是 MoE 层，你可以拆成<strong>很多个小专家</strong>，也可以拆成<strong>几个大专家</strong>。两种极端并存：</p><table tabindex="0"><thead><tr><th>模型</th><th>路由专家总数</th><th>单个专家的中间维度</th><th>风格</th></tr></thead><tbody><tr><td><strong>DeepSeek-V3</strong>（2024）</td><td><strong>256</strong></td><td>2048（小）</td><td>多而小（细粒度）</td></tr><tr><td><strong>Qwen3 235B</strong>（2025）</td><td>128</td><td>中等</td><td>偏多</td></tr><tr><td><strong>Llama 4 Maverick</strong>（2025）</td><td><strong>8</strong></td><td>8192（大）</td><td>少而大</td></tr><tr><td><strong>DeepSeek V4.1-Flash</strong>（2026）</td><td><strong>384</strong></td><td>2048（小）</td><td>超细粒度</td></tr><tr><td><strong>Qwen3.8-Max</strong>（2026）</td><td><strong>512</strong></td><td>2048（小）</td><td>超细粒度</td></tr><tr><td><strong>Kimi K3 / K3.1 Pro</strong>（2026）</td><td><strong>896</strong></td><td>3072（在 3584 维潜空间内计算）</td><td>极细粒度 + 潜空间压缩</td></tr></tbody></table><p>DeepSeek 走的是<strong>细粒度（fine-grained）<strong>路线：把前馈切成几百个小专家；到了 2026 年，Qwen3.8-Max（512 个专家）和 Kimi K3（896 个专家）更是把细粒度推到了极致。Llama 4 则走的是</strong>经典</strong>路线：8 个大专家。</p><p>为什么前沿旗舰越来越偏爱“多而小”？<strong>DeepSeekMoE 论文</strong>的论证很妙：专家越多、越小，<strong>能组合出的“专家搭配”就越多</strong>。8 选 2，只有 28 种组合；256 选 8、乃至 896 选 16，组合数是个天文数字。组合空间越大，不同 token 越能被路由到<strong>更贴合自己</strong>的专家子集，专家也越能各自<strong>深度专精</strong>（一个管代码缩进、一个管化学式、一个管古文……），而不是每个都被迫当“样样通样样松”的万金油。</p><p>代价是：小专家越多，跨卡通信（All-to-All）压力越大。<a href="https://daiw.org/manual/kimi-k3/latent-moe" target="_blank" rel="noreferrer">Kimi K3 的 LatentMoE</a> 为此专门加了一招：先把 7,168 维的 token 投影压到 3,584 维的<strong>潜空间</strong>，再分发给 896 个路由专家计算，直接把跨卡通信体积砍半。</p><h2 id="旋钮二-每个-token-激活几个-top-k" tabindex="-1">旋钮二：每个 token 激活几个（top-k） <a class="header-anchor" href="#旋钮二-每个-token-激活几个-top-k" aria-label="Permalink to &quot;旋钮二：每个 token 激活几个（top-k）&quot;">​</a></h2><p>选出总专家后，还要定<strong>每个 token 实际激活几个</strong>。这个数直接决定“每步算多少”：</p><table tabindex="0"><thead><tr><th>模型</th><th>每 token 激活（路由专家）</th><th>备注</th></tr></thead><tbody><tr><td>Switch Transformer</td><td><strong>1</strong></td><td>最省，top-1</td></tr><tr><td>Llama 4 Maverick</td><td><strong>2</strong></td><td></td></tr><tr><td>DeepSeek-V3</td><td><strong>8</strong></td><td>+ 1 个共享（见旋钮三）= 实际 9 个</td></tr><tr><td>Qwen3 235B</td><td><strong>8</strong></td><td>无共享专家</td></tr><tr><td>DeepSeek V4.1-Flash</td><td><strong>6</strong></td><td>+ 1 个共享 = 实际 7 个（384 选 6）</td></tr><tr><td>Qwen3.8-Max</td><td><strong>10</strong></td><td>+ 1 个共享 = 实际 11 个（512 选 10）</td></tr><tr><td>Kimi K3 / K3.1 Pro</td><td><strong>16</strong></td><td>+ 2 个全维度共享专家（896 选 16）</td></tr></tbody></table><p>激活越多，每个 token 能调用的“脑力”越多、表达越强，但每步计算也越大。这就是<strong>上一章那张“总参数 vs 激活参数”表背后的旋钮</strong>。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>旋钮一和旋钮二要<strong>一起看</strong>。DeepSeek 的“256 个小专家、激活 8+1”和 Llama 4 的“8 个大专家、激活 2”，可能激活参数量相近，但<strong>风格迥异</strong>：前者是“从一大群专才里点几个”，后者是“从几个通才里点一两个”。前者赌的是“专精 + 组合”，后者赌的是“简单 + 稳健”。</p></div><h2 id="旋钮三-要不要一个-万金油-共享专家" tabindex="-1">旋钮三：要不要一个“万金油”共享专家 <a class="header-anchor" href="#旋钮三-要不要一个-万金油-共享专家" aria-label="Permalink to &quot;旋钮三：要不要一个“万金油”共享专家&quot;">​</a></h2><p>这是最能体现设计哲学分歧与演进的一个旋钮。</p><p><strong>共享专家（shared expert）<strong>是一个</strong>永远激活、每个 token 都过</strong>的专家，叠在路由选出的那几个之上。DeepSeek、GLM-4.5、Kimi K2/K3 都留了共享专家（1 到 2 个）。</p><p>它的道理是：<strong>语言里有大量“谁都用得到”的通用知识</strong>（基本语法、常见搭配）。如果没有共享专家，那这些通用能力就得<strong>在每个路由专家里各学一遍</strong>——冗余、浪费。给一个专家“专门负责通用”，常驻在线，就把通用知识从路由专家身上卸下来，<strong>让路由专家腾出手去专精</strong>。分工更干净。</p><p>有趣的是 <strong>Qwen 家族在这一旋钮上的往返</strong>：</p><ul><li><strong>Qwen2.5-MoE</strong> 用了共享专家；</li><li><strong>Qwen3（2025）偏偏把共享专家砍了</strong>——团队在报告里坦诚说，当时在 128 专家的规模下没观察到足够明显的收益，于是干脆去掉图个简单；</li><li><strong>到了 2026 年的 <a href="https://daiw.org/manual/qwen3-8-max/architecture" target="_blank" rel="noreferrer">Qwen3.8-Max</a>（512 个路由专家，稀疏度降到约 2%），共享专家又被重新请了回来</strong>（<code>512 routed + 1 shared</code>）！因为当路由专家拆得极细、每个路由专家被激活的概率极低时，常驻的共享专家成了兜住高频公共变换的压舱石。</li></ul><p><strong>这一去一回，恰恰是读架构最有意思的信号</strong>：同一个设计不是绝对的“对”或“错”，而是在不同的专家粒度与稀疏度下，它的边际收益完全不同。</p><h2 id="三个旋钮-拧出不同性格" tabindex="-1">三个旋钮，拧出不同性格 <a class="header-anchor" href="#三个旋钮-拧出不同性格" aria-label="Permalink to &quot;三个旋钮，拧出不同性格&quot;">​</a></h2><p>把三个旋钮并到一张表，各家的“性格”就跃然纸上：</p><table tabindex="0"><thead><tr><th>模型</th><th>专家（总/激活）</th><th>粒度</th><th>共享专家</th><th>一句话性格</th></tr></thead><tbody><tr><td><strong>DeepSeek-V3 / V4.1-Flash</strong></td><td>256/8 → 384/6</td><td>小（细粒度）</td><td>有（1）</td><td>多而小 + 共享：极致专精与组合</td></tr><tr><td><strong>Llama 4 Maverick</strong></td><td>8 / 2</td><td>大</td><td>无</td><td>少而大：经典、稳健、好实现</td></tr><tr><td><strong>Qwen3 235B</strong></td><td>128 / 8</td><td>中</td><td><strong>无（主动砍掉）</strong></td><td>偏多但从简</td></tr><tr><td><strong>Qwen3.8-Max</strong></td><td>512 / 10</td><td>小（超细粒度）</td><td><strong>有（1，重新加回）</strong></td><td>超细粒度下请回共享专家兜底</td></tr><tr><td><strong>Kimi K3 / K3.1 Pro</strong></td><td>896 / 16</td><td>小（潜空间）</td><td>有（2 个全维）</td><td>LatentMoE 潜空间路由省通信</td></tr><tr><td><strong>GLM-4.5</strong></td><td>多</td><td>——</td><td>有</td><td>借鉴 DeepSeek 路线</td></tr></tbody></table><p>读到这儿，你应该有个体会：<strong>“用不用 MoE”只是第一层；真正见功力的是这三个旋钮怎么拧。</strong> 而拧法背后，是各家对“专精 vs 简单”“组合能力 vs 跨卡通信成本”的不同下注。</p><h2 id="还差一块-拧完旋钮-怎么让它训得起来" tabindex="-1">还差一块：拧完旋钮，怎么让它训得起来 <a class="header-anchor" href="#还差一块-拧完旋钮-怎么让它训得起来" aria-label="Permalink to &quot;还差一块：拧完旋钮，怎么让它训得起来&quot;">​</a></h2><p>三个旋钮定了 MoE 的“形状”，但 MoE 有个众所周知的老大难：<strong>训练时，路由器很容易“偏心”</strong>——把绝大多数 token 都塞给少数几个热门专家，剩下的专家“饿死”、学不到东西，几百个专家白设。这叫<strong>负载不均衡</strong>，是 MoE 能不能训好的命门。各家（尤其 DeepSeek）为此发明了一整套招数，包括一个漂亮的“无辅助损失”方案。这是下一章。👉 <a href="/Front2Full/manual/llm/llm-anatomy/moe-stability">让 MoE 训得稳、又均衡</a></p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] Dai et al. “DeepSeekMoE: Towards Ultimate Expert Specialization in Mixture-of-Experts Language Models.” 2024. arXiv:2401.06066. —— 细粒度专家 + 共享专家的论证。</li><li>[2] DeepSeek-AI. “DeepSeek-V3 Technical Report.” 2024. arXiv:2412.19437. —— 256 专家、激活 8+1 的具体配置。</li><li>[3] Fedus et al. “Switch Transformers.” JMLR 2022. arXiv:2101.03961. —— top-1 路由。</li><li>[4] Qwen Team. “Qwen3 Technical Report.” 2025. arXiv:2505.09388. —— 去掉共享专家的说明。</li><li>[5] Raschka, S. “The Big LLM Architecture Comparison.” 2025. <a href="https://magazine.sebastianraschka.com/p/the-big-llm-architecture-comparison" target="_blank" rel="noreferrer">https://magazine.sebastianraschka.com/p/the-big-llm-architecture-comparison</a> —— 各模型专家配置的横向对比。</li></ul>',29)])])}const c=e(n,[["render",d]]);export{m as __pageData,c as default};
